        fast = fast->next;
    if (fast == NULL)
    {
        printf("NULL\n");
        return 0;
    }
    while (fast->next != NULL)
    {
        fast = fast->next;
        slow = slow->next;
    }
    printf("%d\n", slow->data);
    return 0;
}
