typedef struct LNode
{
    int data;
    struct LNode *next;
} LNode, *LinkList;

/* 按位序奇偶把带头结点单链表 L 拆成 L 与 *B */
void SplitList(LinkList L, LinkList *B)
{
    LinkList p = L->next, ra = L, rb;
    int i = 1;

    *B = (LinkList)malloc(sizeof(LNode));
    (*B)->next = NULL;
    rb = *B;
    while (p != NULL)
    {
        if (i % 2 == 1)
        {
            ra->next = p;
            ra = p;
        }
        else
        {
            rb->next = p;
            rb = p;
        }
        p = p->next;
        i++;
    }
    ra->next = NULL;
    rb->next = NULL;
}

int main(void)
{
    LinkList L, s, r, p, q;
