    {
        if (scanf("%d", &x) != 1)
            return 1;
        s = (LinkList)malloc(sizeof(LNode));
        s->data = x;
        s->next = NULL;
        r->next = s;
        r = s;
    }
    SplitList(L, &q);
    for (s = L->next; s != NULL; s = s->next)
        printf("%d ", s->data);
