#include <stdio.h>
#include <stdlib.h>

typedef struct LNode
{
    int data;
    struct LNode *next;
} LNode, *LinkList;

/* 读入 n 个整数，建立带头结点的单链表 */
static LinkList Create(int n)
{
    LinkList L, r, s;
    int i, x;

    L = (LinkList)malloc(sizeof(LNode));
    L->next = NULL;
    r = L;
    for (i = 0; i < n; i++)
    {
        if (scanf("%d", &x) != 1)
            exit(1);
        s = (LinkList)malloc(sizeof(LNode));
        s->data = x;
        s->next = NULL;
        r->next = s;
        r = s;
    }
    return L;
}

/* 合并两条递增有序单链表，复用结点，返回合并后的头结点 */
LinkList MergeList_L(LinkList La, LinkList Lb)
{
    LinkList pa = La->next, pb = Lb->next, r = La;

    La->next = NULL;
    while (pa != NULL && pb != NULL)
    {
        if (pa->data <= pb->data)
        {
            r->next = pa;
            r = pa;
            pa = pa->next;
        }
        else
        {
            r->next = pb;
            r = pb;
            pb = pb->next;
        }
    }
    r->next = (pa != NULL) ? pa : pb;
    free(Lb);
    return La;
}

int main(void)
{
    LinkList La, Lb, L, s;
    int m, n;

    if (scanf("%d", &m) != 1 || m < 0 || m > 50)
        return 1;
    La = Create(m);
    if (scanf("%d", &n) != 1 || n < 0 || n > 50)
        return 1;
    Lb = Create(n);
    L = MergeList_L(La, Lb);
    for (s = L->next; s != NULL; s = s->next)
        printf("%d ", s->data);
    printf("\n");
    return 0;
}

