#include <stdio.h>

#define MAXSIZE 100

typedef struct
{
    int data[MAXSIZE];
    int length;
} SqList;

/* 把顺序表 L 的前 p 个元素循环移到表尾 */
void LeftRotate(SqList *L, int p)
{
    int i, j, t;

    for (i = 0; i < p; i++)
    {
        t = L->data[0];
        for (j = 0; j < L->length - 1; j++)
            L->data[j] = L->data[j + 1];
        L->data[L->length - 1] = t;
    }
}

int main(void)
{
    SqList L;
    int n, i, x, e, j, ok;

    L.length = 0;
    if (scanf("%d", &n) != 1 || n < 0 || n > MAXSIZE)
        return 1;
    for (i = 0; i < n; i++)
    {
        if (scanf("%d", &x) != 1)
            return 1;
        L.data[i] = x;
    }
    L.length = n;
    if (scanf("%d", &j) != 1 || j < 0 || j > L.length)
        return 1;
    LeftRotate(&L, j);

    for (i = 0; i < L.length; i++)
        printf("%d ", L.data[i]);
    printf("\n");

    return 0;
}

