#include <stdio.h>
#include <stdlib.h>

typedef struct LNode
{
    int data;
    struct LNode *next;
} LNode, *LinkList;

/* 删除递增有序带头结点单链表中所有值重复的结点 */
void DeleteSame(LinkList L)
{
    LinkList p = L->next, q;

    if (p == NULL)
        return;
    q = p->next;
    while (q != NULL)
    {
        if (q->data == p->data)
        {
            p->next = q->next;
            free(q);
            q = p->next;
        }
        else
        {
            p = q;
            q = q->next;
        }
    }
}

int main(void)
{
    LinkList L, s, r, p, q;
    int n, i, x, e, j, ok;

    L = (LinkList)malloc(sizeof(LNode));
    L->next = NULL;
    r = L;
    if (scanf("%d", &n) != 1)
        return 1;
    for (i = 0; i < n; i++)
    {
        if (scanf("%d", &x) != 1)
            return 1;
        s = (LinkList)malloc(sizeof(LNode));
        s->data = x;
        s->next = NULL;
        r->next = s;
        r = s;
    }
    DeleteSame(L);

    for (s = L->next; s != NULL; s = s->next)
        printf("%d ", s->data);
    printf("\n");

    return 0;
}

